def gen(rng):
    def fmt(M):
        return str(len(M)) + '\n' + '\n'.join(' '.join(map(str, r)) for r in M)

    def rand(n, p):
        return [[0 if i == j else int(rng.random() < p) for j in range(n)] for i in range(n)]

    def planted(n, p, flaw=0, c=None):
        M = rand(n, p)
        if c is None:
            c = rng.randrange(n)
        for j in range(n):
            M[c][j] = 0
        for i in range(n):
            if i != c:
                M[i][c] = 1
        others = [k for k in range(n) if k != c]
        if flaw == 1 and others:
            M[rng.choice(others)][c] = 0
        elif flaw == 2 and others:
            M[c][rng.choice(others)] = 1
        return M

    tests = [fmt([[0]]), fmt([[0, 1], [0, 0]]), fmt([[0, 0], [1, 0]]), fmt([[0, 1], [1, 0]]), fmt([[0, 0], [0, 0]])]
    for n in (3, 4, 5, 6, 8):
        for flaw in (0, 0, 1, 2):
            tests.append(fmt(planted(n, rng.choice([0.2, 0.5, 0.8]), flaw)))
        tests.append(fmt(planted(n, 0.5, 0, 0)))
        tests.append(fmt(planted(n, 0.5, 0, n - 1)))
        tests.append(fmt(rand(n, 0.5)))
        tests.append(fmt(rand(n, 0.9)))
    N = 700
    tests.append(fmt(planted(N, 0.5, 0)))
    tests.append(fmt(planted(N, 0.5, 1)))
    tests.append(fmt(planted(N, 0.5, 2)))
    tests.append(fmt(planted(N, 0.5, 0, N - 1)))
    tests.append(fmt(rand(N, 0.9)))
    return tests

